package rosemary_and_thyme.models.requests

import kotlinx.serialization.Serializable
import rosemary_and_thyme.models.recipe.IngredientDTO
import rosemary_and_thyme.models.recipe.InstructionDTO

/**
 * Client-supplied data used to create a recipe.
 * Identity, ownership, creation time, counters, and initial privacy are controlled by the server.
 *
 * @property imageIds identifiers generated by the client for images belonging to the recipe
 */
@Serializable
data class PostRecipeRequest(
    val title: String,
    val description: String,
    val portions: Short,
    val difficulty: Short,
    val sideNote: String,
    val imageIds: Set<String>,
    val ingredients: Map<String, IngredientDTO>,
    val instructions: Map<String, InstructionDTO>,
    val ingredientsOrder: List<String>,
    val instructionsOrder: List<String>,
    val heroImagesOrder: List<String>
)
